    // MARK: Owner inputs

    private static var priced: [Original] { originals.filter(\.isPriced) }
    private static var unpriced: [Original] { originals.filter { !$0.isPriced } }
    private static func original(_ marketID: String, _ side: Side) -> Original {
        originals.first { $0.marketID == marketID && $0.side == side }!
    }
    private static var kok: Original { original("1347941", .yes) }
    private static var kokNo: Original { original("1347941", .no) }
    private static var placeholder1: Original { original("1347961", .yes) }

    private static func trades(_ original: Original, _ frame: Frame) -> [Trade] {
        frame == .before ? Array(original.trades.prefix(original.beforeCount)) : original.trades
    }

    private static func point(_ trade: Trade) -> FieldHistoryPoint10868 {
        FieldHistoryPoint10868(id: trade.id, x: trade.x, probability: trade.probability, style: trade.style)
    }

    private static func tint(_ shape: FieldHistoryShape10868) -> Color {
        shape == .circle ? .blue : shape == .triangle ? .orange : .gray
    }

    private static func baselineProvenance(_ trade: Trade) -> String {
        "\(trade.clock) · last trade before race day in Milan"
    }

    private static func baselineReading(_ original: Original) -> FieldHistoryReading10868 {
        guard let baseline = original.baseline else { return .absent(words: "Unavailable") }
        return .observation(pointID: baseline.id, figure: baseline.figure, provenance: baselineProvenance(baseline))
    }

    private static func runs(_ trades: [Trade]) -> [FieldHistoryRun10868] {
        trades.map { FieldHistoryRun10868(id: "constructed-run:\($0.id)", points: [point($0)]) }
    }

    private static func series(_ original: Original, _ frame: Frame,
                               recorded: FieldHistoryReading10868? = nil,
                               runs: [FieldHistoryRun10868]? = nil,
                               before: FieldHistoryReading10868? = nil) -> FieldHistorySeries10868 {
        FieldHistorySeries10868(
            id: original.seriesID, name: original.name, shape: original.shape, tint: tint(original.shape),
            runs: runs ?? Self.runs(trades(original, frame)),
            links: [], labelPointID: nil,
            before: before ?? baselineReading(original),
            recorded: recorded ?? .absent(words: unboundWords),
            absentWords: nil,
            choose: nil)
    }

    private static func action(_ id: String, _ label: String, _ spoken: String? = nil,
                               available: Bool = true) -> FieldHistoryAction10868 {
        FieldHistoryAction10868(id: id, label: label, spokenLabel: spoken, isAvailable: available)
    }

    private static func absence(_ original: Original) -> FieldHistoryPlotAbsence10868 {
        FieldHistoryPlotAbsence10868(title: "No retained trades",
                                     words: "This original \(original.side.rawValue) outcome has no traded history in this capture.")
    }

    private static func meaningNote(_ original: Original) -> String {
        original.side == .no
            ? "Chance of not winning gold; it is not a chance of winning a medal."
            : "Chance of winning gold; it is not a chance of winning any medal."
    }

    /// The owner's headline labels, as the reference reader words them.
    private static func selectedReadout(_ frame: Frame, inspected trade: Trade?) -> FieldHistorySelectedReadout10868 {
        if frame == .before {
            return FieldHistorySelectedReadout10868(beforeLabel: nil, inspectedLabel: "Inspected before race day")
        }
        let earlier = trade.map { $0.x < raceDay } ?? false
        return FieldHistorySelectedReadout10868(beforeLabel: "Before race day",
                                                inspectedLabel: earlier ? "Inspected earlier trade" : "Recorded chance")
    }

    private static func ceiling(_ original: Original, _ frame: Frame, full: Bool) -> Double {
        full ? 1 : frame == .before ? original.beforeCeiling : original.finalCeiling
    }

    private static func input(_ original: Original, _ frame: Frame,
                              series: FieldHistorySeries10868? = nil,
                              inspected trade: Trade? = nil,
                              inspection: FieldHistoryInspection10868? = nil,
                              selection: FieldHistoryOriginalSelection10868? = nil,
                              full: Bool = false,
                              absent: Bool = false,
                              showsKey: Bool = false,
                              controls: Bool = false,
                              plotHeight: CGFloat = 302,
                              layout: FieldHistoryLayout10868 = .focused) -> FieldHistoryInput10868 {
        let before = frame == .before
        let top = ceiling(original, frame, full: full)
        let words = tickWords[top]!
        var input = FieldHistoryInput10868(
            title: original.meaning,
            caption: "\(original.name) · original \(original.side.rawValue)",
            series: [series ?? Self.series(original, frame)],
            selection: selection ?? .series(id: original.seriesID, missingWords: missingWords),
            domain: FieldHistoryDomain10868(lower: domainLower, upper: before ? raceDay : reportAt),
            ceiling: top,
            yTicks: [FieldHistoryTick10868(value: 0, lines: [words[0]]),
                     FieldHistoryTick10868(value: top / 2, lines: [words[1]]),
                     FieldHistoryTick10868(value: top, lines: [words[2]])],
            xTicks: before
                ? [FieldHistoryTick10868(value: domainLower, lines: ["Feb 6"]),
                   FieldHistoryTick10868(value: 1_770_762_518.5, lines: ["Feb 10"]),
                   FieldHistoryTick10868(value: raceDay, lines: ["Feb 14"])]
                : [FieldHistoryTick10868(value: domainLower, lines: ["Feb 6"]),
                   FieldHistoryTick10868(value: 1_770_798_183, lines: ["Feb 11"]),
                   FieldHistoryTick10868(value: reportAt, lines: ["Feb 15"])],
            guides: before ? [] : [FieldHistoryGuide10868(id: "constructed-guide:race-day", x: raceDay, label: "Race day · Milan")],
            breaks: [],
            readout: .singleBefore(label: "Before race day"),
            markKey: FieldHistoryMarkKey10868(hollow: "Hollow: before race day", filled: "Filled: later recorded"),
            comparisonExplanation: nil,
            notes: [meaningNote(original)],
            summary: "\(original.name), \(original.meaning). Original \(original.side.rawValue) token trades, zero to \(words[2]). Dots are recorded trades, not a continuous forecast.",
            plotHeight: plotHeight, unboundReadingWords: unboundWords,
            plotUnavailableWords: "Original history unavailable",
            windows: controls ? FieldHistoryWindows10868(groupLabel: "Phase", choices: [
                FieldHistoryWindowChoice10868(action: action("constructed-phase:before", "Before race day"), isSelected: before),
                FieldHistoryWindowChoice10868(action: action("constructed-phase:final", "Final"), isSelected: !before),
            ]) : nil,
            scale: controls ? action("constructed-scale", full ? "Closer scale" : "0–100%") : nil,
            moreOriginals: nil,
            details: controls ? action("constructed-details", "Gold prop details") : nil,
            expand: controls ? action("constructed-expand", "Expand", "Expand recorded chance") : nil,
            inspect: controls ? action("constructed-before-race-day", "Before race day",
                                       "Inspect the last trade before race day") : nil,
            previous: controls ? action("constructed-earlier", "Earlier") : nil,
            next: controls ? action("constructed-later", "Later") : nil,
            inspection: inspection ?? trade.map { Self.inspection(original, $0) },
            layout: layout)
        input.selectedReadout = selectedReadout(frame, inspected: trade)
        input.inspectionRingShape = .circle
        input.plotAbsence = absent ? absence(original) : nil
        input.showsKey = showsKey
        return input
    }

    private static func inspection(_ original: Original, _ trade: Trade,
                                   choices: [FieldHistoryInspectionChoice10868] = []) -> FieldHistoryInspection10868 {
        FieldHistoryInspection10868(x: trade.x, caption: trade.clock,
                                    selections: [original.seriesID: .point(id: trade.id, spoken: "\(trade.figure), \(trade.clock)")],
                                    choices: choices, choicePresentation: .slider(label: "Inspect original outcome trade"),
                                    note: nil)
    }

    private static func observed(_ trade: Trade) -> FieldHistoryReading10868 {
        .observation(pointID: trade.id, figure: trade.figure, provenance: trade.clock)
    }

    /// One original inspected at one of its own trades, exactly as the owner holds it.
    private static func inspected(_ original: Original, _ frame: Frame, _ trade: Trade,
                                  full: Bool = false, showsKey: Bool = false) -> FieldHistoryInput10868 {
        input(original, frame, series: series(original, frame, recorded: observed(trade)),
              inspected: trade, full: full, showsKey: showsKey)
    }

    private static func expectedSlots(_ original: Original, _ frame: Frame,
                                      _ trade: Trade) -> [FieldHistoryReadoutSlot10868] {
        let label = selectedReadout(frame, inspected: trade).inspectedLabel
        let inspectedSlot = FieldHistoryReadoutSlot10868(label: label, display: .figure(trade.figure, provenance: trade.clock))
        guard frame == .final, let baseline = original.baseline else { return [inspectedSlot] }
        return [FieldHistoryReadoutSlot10868(label: "Before race day",
                                             display: .figure(baseline.figure, provenance: baselineProvenance(baseline))),
                inspectedSlot]
    }

    /// The selected original's headline slots; none when the headline names no original.
    private static func slots(_ input: FieldHistoryInput10868) -> [FieldHistoryReadoutSlot10868] {
        guard case .original(_, let slots) = FieldHistoryGeometry10868.selectedSummary(input) else { return [] }
        return slots
    }

    private static func marks(_ input: FieldHistoryInput10868) -> [FieldHistoryPoint10868] {
        input.series.flatMap { FieldHistoryGeometry10868.marks($0, in: input) }
    }

    /// Expand, scale, inspect, previous, next, then each period — with the
    /// informative flag the view passes for each.
    private static func chartControls(_ input: FieldHistoryInput10868) -> [(FieldHistoryAction10868?, Bool)] {
        let fixed: [(FieldHistoryAction10868?, Bool)] = [(input.expand, false), (input.scale, true), (input.inspect, false),
                                                         (input.previous, false), (input.next, false)]
        let periods: [(FieldHistoryAction10868?, Bool)] = (input.windows?.choices ?? []).map { ($0.action, true) }
        return fixed + periods
    }

    private static func chartStates(_ input: FieldHistoryInput10868,
                                    hasCallback: Bool) -> [FieldHistoryControlState10868] {
        chartControls(input).map {
            FieldHistoryGeometry10868.chartControlState($0.0, informative: $0.1, hasCallback: hasCallback, in: input)
        }
    }

