    }

    func testEveryFinalTradeOfEveryOriginalIsItsOwnUnlinkedDotWithItsRetainedStyle() {
        var placed = 0, hollow = 0
        for original in Self.priced {
            let input = Self.input(original, .final)
            XCTAssertTrue(FieldHistoryGeometry10868.isDrawable(input), original.seriesID)
            // Every retained trade is placed, as itself, in owner order.
            XCTAssertEqual(Self.marks(input), original.trades.map(Self.point), original.seriesID)
            let series = input.series[0]
            XCTAssertTrue(FieldHistoryGeometry10868.lines(series, in: input).isEmpty)
            XCTAssertTrue(series.runs.allSatisfy { FieldHistoryGeometry10868.drawnRuns($0, in: input).map(\.count) == [1] })
            XCTAssertTrue(series.links.isEmpty)
            XCTAssertFalse(FieldHistoryGeometry10868.drawsComparisonLink(input))
            XCTAssertNil(FieldHistoryGeometry10868.comparisonKeyWords(input))
            XCTAssertTrue(FieldHistoryGeometry10868.drawsStyle(.hollow, in: input))
            XCTAssertEqual(FieldHistoryGeometry10868.drawsStyle(.filled, in: input),
                           original.trades.count > original.beforeCount, original.seriesID)
            XCTAssertEqual(input.guides.map(\.x), [Self.raceDay])
            XCTAssertNil(FieldHistoryGeometry10868.plotAbsence(input))
            placed += Self.marks(input).count
            hollow += Self.marks(input).filter { $0.style == .hollow }.count
        }
        XCTAssertEqual(placed, 3_632)
        XCTAssertEqual(hollow, 1_271)
        // Rio Yamada No and Kristina Silaeva No have no later trade: no filled dot is made for them.
        XCTAssertEqual(Self.priced.filter { $0.trades.count == $0.beforeCount }.map { "\($0.name) \($0.side.rawValue)" },
                       ["Kristina Silaeva (KAZ) No", "Rio Yamada (JPN) No"])
    }

