    func testEveryRetainedTradeInspectsToItsOwnExactFigureClockAndCircularRing() {
        var inspected = 0
        for original in Self.priced {
            for frame in [Frame.before, .final] {
                for trade in Self.trades(original, frame) {
                    let input = Self.inspected(original, frame, trade)
                    XCTAssertEqual(FieldHistoryGeometry10868.inspectedPoint(input.series[0], in: input), Self.point(trade))
                    XCTAssertEqual(FieldHistoryGeometry10868.inspectionRingShape(input.series[0], in: input), .circle)
                    XCTAssertEqual(FieldHistoryGeometry10868.selectedSummary(input),
                                   .original(input.series[0], slots: Self.expectedSlots(original, frame, trade)), trade.id)
