                        .contains("\(original.name): \(trade.figure), \(trade.clock)"))
                    inspected += 1
                }
            }
        }
        XCTAssertEqual(inspected, 3_632 + 1_271)
        // The single-original reader names its original in the headline; no field key repeats it.
        let reader = Self.inspected(Self.kok, .final, Self.kok.trades[0])
        XCTAssertEqual(FieldHistoryGeometry10868.blocksAbovePlot(reader), [.selectedSummary])
        XCTAssertEqual(FieldHistoryGeometry10868.blocksBelowPlot(reader), [])
        XCTAssertEqual(Self.slots(reader).map(\.label), ["Before race day", "Inspected earlier trade"])
        XCTAssertEqual(Self.slots(reader).map(\.display), [.figure("78%", provenance: "Feb 14, 2:45:25 PM · last trade before race day in Milan"),
                                                            .figure("68%", provenance: "Feb 6, 4:20:45 PM")])
    }

    func testOwnBaselinesLeadTheFinalAndEachNoSideKeepsItsOwnIndependentTrades() {
        for original in Self.priced {
            let baseline = original.baseline!
            // The baseline is this original's own last trade before race day, at its reference index.
            XCTAssertEqual(original.trades[original.baselineIndex].id, baseline.id)
            XCTAssertEqual(original.baselineIndex, original.beforeCount - 1)
            XCTAssertEqual(original.beforeDefaultID, baseline.id)
            XCTAssertEqual(original.finalDefaultID, original.trades.last?.id)
            // The owner's default inspections: the baseline before race day; the last real trade at the final.
            let before = Self.inspected(original, .before, baseline)
            XCTAssertEqual(Self.slots(before), Self.expectedSlots(original, .before, baseline))
            let last = original.trades[original.trades.count - 1]
            let final = Self.inspected(original, .final, last)
            XCTAssertEqual(Self.slots(final), Self.expectedSlots(original, .final, last))
            XCTAssertEqual(Self.slots(final).first?.display,
                           .figure(baseline.figure, provenance: Self.baselineProvenance(baseline)))
            // The final ends at the original's own last real trade, never a 0% or 100% result end.
            XCTAssertEqual(Self.marks(final).last, Self.point(last))
        }
        XCTAssertEqual(Self.kok.baseline?.figure, "78%")
        XCTAssertEqual(Self.kokNo.baseline?.figure, "23%")
        for marketID in Set(Self.priced.map(\.marketID)) {
            let yes = Self.original(marketID, .yes), no = Self.original(marketID, .no)
            // Independent sides: their own trade ids, counts and clocks; No is never 1 − Yes.
            XCTAssertTrue(Set(yes.trades.map(\.id)).isDisjoint(with: no.trades.map(\.id)), marketID)
            XCTAssertNotEqual(yes.trades.count, no.trades.count, marketID)
            XCTAssertNotEqual(Set(yes.trades.map(\.x)), Set(no.trades.map(\.x)), marketID)
            let noInput = Self.input(no, .final)
            XCTAssertEqual(Self.marks(noInput), no.trades.map(Self.point))
            XCTAssertEqual(noInput.title, "Doesn\u{2019}t win gold")
            XCTAssertEqual(noInput.notes, ["Chance of not winning gold; it is not a chance of winning a medal."])
        }
        // Yes 78% and No 23% total 101%: each side's own market, nothing complemented.
        XCTAssertEqual((Self.kok.baseline!.probability + Self.kokNo.baseline!.probability) * 100, 100.99999991, accuracy: 1e-9)
    }

    func testAll32OriginalsWithoutRetainedTradesShowCompactAbsenceAndNoZero() {
        for original in Self.unpriced {
            for frame in [Frame.before, .final] {
                let input = Self.input(original, frame, absent: true, controls: true)
                XCTAssertEqual(FieldHistoryGeometry10868.plotAbsence(input), Self.absence(original))
                XCTAssertEqual(FieldHistoryGeometry10868.plotAbsence(input).flatMap(FieldHistoryGeometry10868.absenceWords),
                               "This original \(original.side.rawValue) outcome has no traded history in this capture.")
                XCTAssertFalse(FieldHistoryGeometry10868.showsPlot(input))
                XCTAssertFalse(FieldHistoryGeometry10868.isDrawable(input))
                XCTAssertTrue(Self.marks(input).isEmpty)
                XCTAssertTrue(FieldHistoryGeometry10868.placedYTicks(input).isEmpty)
                XCTAssertTrue(FieldHistoryGeometry10868.placedXTicks(input).isEmpty)
                XCTAssertTrue(FieldHistoryGeometry10868.placedGuides(input).isEmpty)
                XCTAssertFalse(FieldHistoryGeometry10868.drawsStyle(.hollow, in: input))
                XCTAssertFalse(FieldHistoryGeometry10868.drawsStyle(.filled, in: input))
                // Chart-only controls are gone; the host's independent Details remains.
                XCTAssertTrue(Self.chartStates(input, hasCallback: true).allSatisfy { $0 == .hidden })
                XCTAssertNil(FieldHistoryGeometry10868.shownWindows(input))
                XCTAssertNil(FieldHistoryGeometry10868.shownInspection(input))
                XCTAssertEqual(FieldHistoryGeometry10868.controlState(input.details, informative: false, hasCallback: true, in: input),
                               .live(id: "constructed-details"))
                // Identity, meaning and the owner's missing readouts stay; nothing reads as 0%.
                XCTAssertEqual(input.title, original.meaning)
                XCTAssertEqual(input.notes, [Self.meaningNote(original)])
                XCTAssertEqual(FieldHistoryGeometry10868.blocksAbovePlot(input), [.selectedSummary])
                XCTAssertEqual(FieldHistoryGeometry10868.blocksBelowPlot(input), [])
                let expected: [FieldHistoryReadoutSlot10868] = frame == .before
                    ? [FieldHistoryReadoutSlot10868(label: "Inspected before race day", display: .words(Self.unboundWords))]
                    : [FieldHistoryReadoutSlot10868(label: "Before race day", display: .words("Unavailable")),
                       FieldHistoryReadoutSlot10868(label: "Recorded chance", display: .words(Self.unboundWords))]
                XCTAssertEqual(FieldHistoryGeometry10868.selectedSummary(input), .original(input.series[0], slots: expected))
                XCTAssertFalse(expected.map(FieldHistoryGeometry10868.spokenSlot).joined().contains("%"))
                XCTAssertNil(FieldHistoryGeometry10868.keyNote(input.series[0], in: input))
            }
        }
        XCTAssertEqual(Self.unpriced.count * 2, 64)
    }

    func testExplicitAbsenceHidesDeliberatelyPopulatedStalePlotFieldsAndControls() {
        // An unpriced original handed stale Kok trades, a stale inspection, a stale observation
        // reading and every chart control: the explicit absence must show none of them.
        let stale = Self.kok.trades
        let staleTrade = stale[100]
        let staleSeries = Self.series(Self.placeholder1, .final, recorded: Self.observed(staleTrade),
                                      runs: Self.runs(stale), before: Self.observed(stale[46]))
        let staleInspection = Self.inspection(Self.placeholder1, staleTrade, choices: [
            FieldHistoryInspectionChoice10868(id: "constructed-choice:a", lines: ["a"], spoken: "a", isSelected: true),
            FieldHistoryInspectionChoice10868(id: "constructed-choice:b", lines: ["b"], spoken: "b", isSelected: false),
        ])
        let absent = Self.input(Self.placeholder1, .final, series: staleSeries, inspected: staleTrade,
                                inspection: staleInspection, full: true, absent: true, controls: true)
        XCTAssertFalse(FieldHistoryGeometry10868.isDrawable(absent))
        XCTAssertTrue(Self.marks(absent).isEmpty)
        XCTAssertTrue(FieldHistoryGeometry10868.lines(absent.series[0], in: absent).isEmpty)
        XCTAssertNil(FieldHistoryGeometry10868.inspectedPoint(absent.series[0], in: absent))
        XCTAssertTrue(FieldHistoryGeometry10868.placedYTicks(absent).isEmpty)
        XCTAssertTrue(FieldHistoryGeometry10868.placedGuides(absent).isEmpty)
        XCTAssertFalse(FieldHistoryGeometry10868.drawsStyle(.hollow, in: absent))
        XCTAssertFalse(FieldHistoryGeometry10868.drawsStyle(.filled, in: absent))
        XCTAssertTrue(Self.chartStates(absent, hasCallback: true).allSatisfy { $0 == .hidden })
        XCTAssertTrue(Self.chartStates(absent, hasCallback: false).allSatisfy { $0 == .hidden })
        XCTAssertNil(FieldHistoryGeometry10868.shownWindows(absent))
        XCTAssertNil(FieldHistoryGeometry10868.shownInspection(absent))
        // No stale figure reaches the headline: observation readings bind to nothing undrawn.
        XCTAssertEqual(Self.slots(absent), [
            FieldHistoryReadoutSlot10868(label: "Before race day", display: .words(Self.unboundWords)),
            FieldHistoryReadoutSlot10868(label: "Recorded chance", display: .words(Self.unboundWords)),
        ])
        // A stale inspected absence is not borrowed either.
        let staleAbsence = FieldHistoryInspection10868(x: staleTrade.x, caption: "stale",
                                                       selections: [Self.placeholder1.seriesID: .absent(words: "Not recorded")],
                                                       choices: [], choicePresentation: .buttons(groupLabel: "Trades"), note: nil)
        let absentWords = Self.input(Self.placeholder1, .final, series: staleSeries, inspection: staleAbsence,
                                     full: true, absent: true)
        XCTAssertNil(FieldHistoryGeometry10868.inspectedAbsentWords(absentWords.series[0], in: absentWords))
        XCTAssertNil(FieldHistoryGeometry10868.keyNote(absentWords.series[0], in: absentWords))
        XCTAssertEqual(FieldHistoryGeometry10868.controlState(absent.details, informative: false, hasCallback: true, in: absent),
                       .live(id: "constructed-details"))
        // The same stale fields without the opt-in draw as before — absence is the owner's choice, never inferred.
        let drawn = Self.input(Self.placeholder1, .final, series: staleSeries, inspected: staleTrade,
                               inspection: staleInspection, full: true, absent: false, controls: true)
        XCTAssertTrue(FieldHistoryGeometry10868.showsPlot(drawn))
        XCTAssertEqual(Self.marks(drawn).count, 155)
        XCTAssertEqual(FieldHistoryGeometry10868.inspectedPoint(drawn.series[0], in: drawn), Self.point(staleTrade))
        XCTAssertEqual(Self.chartStates(drawn, hasCallback: true), [.live(id: "constructed-expand"), .live(id: "constructed-scale"),
                       .live(id: "constructed-before-race-day"), .live(id: "constructed-earlier"), .live(id: "constructed-later"),
                       .live(id: "constructed-phase:before"), .live(id: "constructed-phase:final")])
        XCTAssertEqual(FieldHistoryGeometry10868.shownInspection(drawn), staleInspection)
        // A priced original under the opt-in shows absence too: points never decide it.
        let pricedAbsent = Self.input(Self.kok, .final, absent: true)
        XCTAssertFalse(FieldHistoryGeometry10868.showsPlot(pricedAbsent))
        XCTAssertTrue(Self.marks(pricedAbsent).isEmpty)
    }

