        // Every layout keeps its blocks exactly.
        var layouts = Self.input(Self.kok, .final, showsKey: true)
        var above: [[FieldHistoryReadoutBlock10868]] = [], below: [[FieldHistoryReadoutBlock10868]] = []
        for layout in FieldHistoryLayout10868.allCases {
            layouts.layout = layout
            above.append(FieldHistoryGeometry10868.blocksAbovePlot(layouts))
            below.append(FieldHistoryGeometry10868.blocksBelowPlot(layouts))
        }
        XCTAssertEqual(above, [[.selectionWords, .key], [.selectedSummary], []])
        XCTAssertEqual(below, [[], [.key], [.selectionWords, .key]])
        // Chart-only helpers equal the existing ones while the plot is shown.
        let controls = Self.input(Self.kok, .final, inspected: Self.kok.trades[3], controls: true)
        for hasCallback in [true, false] {
            let existing = Self.chartControls(controls).map {
                FieldHistoryGeometry10868.controlState($0.0, informative: $0.1, hasCallback: hasCallback, in: controls)
            }
            XCTAssertEqual(existing.count, 7)
            XCTAssertEqual(Self.chartStates(controls, hasCallback: hasCallback), existing)
        }
        XCTAssertEqual(FieldHistoryGeometry10868.shownWindows(controls), controls.windows)
        XCTAssertEqual(FieldHistoryGeometry10868.shownInspection(controls), controls.inspection)
        // Owner plot heights stay literal; they establish no rendered fit.
        XCTAssertEqual(FieldHistoryGeometry10868.plotHeight(Self.input(Self.kok, .final).plotHeight), 302)
        XCTAssertEqual(FieldHistoryGeometry10868.plotHeight(Self.input(Self.kok, .final, plotHeight: 370).plotHeight), 370)
    }

    func testHidingTheKeyKeepsTheSelectedOriginalItsReadoutsRunsAndSelectionWords() {
        let trade = Self.kok.trades[120]
        for layout in FieldHistoryLayout10868.allCases {
            var shown = Self.inspected(Self.kok, .final, trade, showsKey: true)
            var hidden = Self.inspected(Self.kok, .final, trade, showsKey: false)
            shown.layout = layout
            hidden.layout = layout
            XCTAssertEqual(FieldHistoryGeometry10868.blocksAbovePlot(hidden),
                           FieldHistoryGeometry10868.blocksAbovePlot(shown).filter { $0 != .key })
            XCTAssertEqual(FieldHistoryGeometry10868.blocksBelowPlot(hidden),
                           FieldHistoryGeometry10868.blocksBelowPlot(shown).filter { $0 != .key })
            XCTAssertFalse((FieldHistoryGeometry10868.blocksAbovePlot(hidden) + FieldHistoryGeometry10868.blocksBelowPlot(hidden))
                .contains(.key))
            XCTAssertEqual(FieldHistoryGeometry10868.selectedSummary(hidden), FieldHistoryGeometry10868.selectedSummary(shown))
            XCTAssertEqual(Self.marks(hidden), Self.marks(shown))
            XCTAssertEqual(hidden.series[0].runs, shown.series[0].runs)
            XCTAssertEqual(FieldHistoryGeometry10868.readoutSlots(hidden.series[0], in: hidden),
                           FieldHistoryGeometry10868.readoutSlots(shown.series[0], in: shown))
            XCTAssertEqual(FieldHistoryGeometry10868.inspectedPoint(hidden.series[0], in: hidden), Self.point(trade))
            XCTAssertTrue(FieldHistoryGeometry10868.drawsStyle(.filled, in: hidden))
            // A withdrawn selection keeps its notice wherever the composition places it.
            let withdrawn = Self.input(Self.kok, .final, inspected: trade,
                                   selection: .unavailable(words: "This original is no longer offered"),
                                   showsKey: false, layout: layout)
            XCTAssertEqual(FieldHistoryGeometry10868.selectionWords(withdrawn), "This original is no longer offered")
            let blocks = FieldHistoryGeometry10868.blocksAbovePlot(withdrawn) + FieldHistoryGeometry10868.blocksBelowPlot(withdrawn)
            XCTAssertTrue(blocks.contains(layout == .focused ? .selectedSummary : .selectionWords), "\(layout)")
        }
        XCTAssertEqual(FieldHistoryGeometry10868.selectedSummary(
            Self.input(Self.kok, .final, selection: .unavailable(words: "This original is no longer offered"))),
                       .words("This original is no longer offered"))
        // The key and the absence are independent opt-ins.
        let absentKeyed = Self.input(Self.placeholder1, .final, absent: true, showsKey: true)
        XCTAssertEqual(FieldHistoryGeometry10868.blocksBelowPlot(absentKeyed), [.key])
        XCTAssertTrue(FieldHistoryGeometry10868.showsPlot(Self.input(Self.kok, .final, showsKey: false)))
    }

    func testCloserAndFullOwnerScalesPlaceEveryOwnTradeIncludingTinyChances() {
        for original in Self.priced {
            for frame in [Frame.before, .final] {
                let own = Self.trades(original, frame)
                let top = Self.ceiling(original, frame, full: false)
                // ARCHIVED closer scale: the smallest reference step at or above the frame's own highest trade.
                XCTAssertEqual(top, Self.scaleSteps.first { $0 >= own.map(\.probability).max()! }, original.seriesID)
                for full in [false, true] {
                    let input = Self.input(original, frame, full: full)
                    XCTAssertTrue(FieldHistoryGeometry10868.isDrawable(input))
                    XCTAssertEqual(Self.marks(input), own.map(Self.point), "\(original.seriesID) full=\(full)")
                    XCTAssertEqual(FieldHistoryGeometry10868.placedYTicks(input).map(\.lines), Self.tickWords[input.ceiling]!.map { [$0] })
                    XCTAssertEqual(FieldHistoryGeometry10868.placedXTicks(input).count, 3)
                }
            }
        }
        // Tiny chances keep a readable closer scale.
        XCTAssertEqual(Self.priced.filter { $0.finalCeiling == 0.01 }.map { "\($0.name) \($0.side.rawValue)" },
                       ["Rio Yamada (JPN) Yes"])
        XCTAssertEqual(Self.priced.filter { $0.beforeCeiling == 0.01 }.map { "\($0.name) \($0.side.rawValue)" },
                       ["Sofia Thorup (DEN) Yes", "Serena Pergher (ITA) Yes", "Rio Yamada (JPN) Yes",
                        "Anna Boersma (NED) Yes", "Ying-Chu Chen (TPE) Yes"])
        let all = Self.priced.flatMap(\.trades)
        XCTAssertEqual(all.map(\.probability).min(), 0.001)
        XCTAssertEqual(all.map(\.probability).max(), 0.999)
        // No synthetic endpoint: nothing at 0 or 100%, and no more dots than retained trades.
        XCTAssertFalse(all.contains { $0.probability == 0 || $0.probability == 1 })
        XCTAssertEqual(Self.priced.map { Self.marks(Self.input($0, .final, full: true)).count }.reduce(0, +), 3_632)
    }

    func testSelectionAndPhaseChangesKeepTheSameOriginalAndOwnerTargetsAreExact() {
        let original = Self.kok
        let first = Self.inspected(original, .final, original.trades[0])
        let later = Self.inspected(original, .final, original.trades[140])
        // Another inspected trade changes only the reading: same original, runs and marks.
        XCTAssertEqual(first.series[0].id, later.series[0].id)
        XCTAssertEqual(first.series[0].runs, later.series[0].runs)
        XCTAssertEqual(Self.marks(first), Self.marks(later))
        XCTAssertNotEqual(Self.slots(first), Self.slots(later))
        XCTAssertEqual(Self.slots(later).map(\.label), ["Before race day", "Recorded chance"])
        // Exact slider targets: one owner choice per own trade, handed back by index, never snapped.
        let choices = original.trades.enumerated().map { index, trade in
            FieldHistoryInspectionChoice10868(id: "constructed-choice:\(trade.id)", lines: [trade.figure, trade.clock],
                                              spoken: "\(trade.figure), \(trade.clock)", isSelected: index == 140)
        }
        let held = Self.input(original, .final, inspection: Self.inspection(original, original.trades[140], choices: choices),
                              controls: true)
        XCTAssertEqual(FieldHistoryGeometry10868.sliderIndex(held.inspection!.choices), 140)
        XCTAssertEqual(FieldHistoryGeometry10868.sliderChoiceID(at: 46, choices: choices), "constructed-choice:\(original.trades[46].id)")
        XCTAssertNil(FieldHistoryGeometry10868.sliderChoiceID(at: 140, choices: choices))
        // A chart tap hands back a domain position for the owner to resolve; no nearest trade is picked.
        let rect = CGRect(x: 0, y: 0, width: 300, height: 302)
        XCTAssertEqual(FieldHistoryGeometry10868.domainValue(atX: 150, domain: held.domain, in: rect),
                       (Self.domainLower + Self.reportAt) / 2)
        // Earlier / Before race day / Later hand back the owner's exact ids; static without a callback.
        XCTAssertEqual(Array(Self.chartStates(held, hasCallback: true).prefix(5)),
                       [.live(id: "constructed-expand"), .live(id: "constructed-scale"), .live(id: "constructed-before-race-day"),
                        .live(id: "constructed-earlier"), .live(id: "constructed-later")])
        XCTAssertEqual(Array(Self.chartStates(held, hasCallback: false).prefix(5)),
                       [.hidden, .shownStatic, .hidden, .hidden, .hidden])
        let atStart = FieldHistoryInput10868(
            title: held.title, caption: held.caption, series: held.series, selection: held.selection, domain: held.domain,
            ceiling: held.ceiling, yTicks: held.yTicks, xTicks: held.xTicks, guides: held.guides, breaks: held.breaks,
            readout: held.readout, markKey: held.markKey, comparisonExplanation: nil, notes: held.notes,
            summary: held.summary, plotHeight: held.plotHeight, unboundReadingWords: held.unboundReadingWords,
            plotUnavailableWords: held.plotUnavailableWords, windows: held.windows, scale: held.scale,
            moreOriginals: nil, details: held.details, expand: held.expand, inspect: held.inspect,
            previous: Self.action("constructed-earlier", "Earlier", available: false), next: held.next,
            inspection: held.inspection, layout: .focused)
        XCTAssertNil(FieldHistoryGeometry10868.adjustableID(atStart.previous, hasCallback: true, in: atStart))
        XCTAssertEqual(FieldHistoryGeometry10868.adjustableID(atStart.next, hasCallback: true, in: atStart), "constructed-later")
        // A phase change keeps the original; its before frame is its own earlier trades only.
        let before = Self.inspected(original, .before, original.trades[0])
        XCTAssertEqual(before.series[0].id, first.series[0].id)
        XCTAssertEqual(before.series[0].name, first.series[0].name)
        XCTAssertEqual(before.series[0].shape, first.series[0].shape)
        XCTAssertEqual(Self.marks(before), Array(Self.marks(first).prefix(original.beforeCount)))
        XCTAssertEqual(FieldHistoryGeometry10868.inspectedPoint(before.series[0], in: before),
                       FieldHistoryGeometry10868.inspectedPoint(first.series[0], in: first))
        // A later trade is not in the before frame and is never placed there.
        let outside = Self.inspected(original, .before, original.trades[100])
        XCTAssertNil(FieldHistoryGeometry10868.inspectedPoint(outside.series[0], in: outside))
        XCTAssertEqual(Self.slots(outside).map(\.display), [.words(Self.unboundWords)])
    }

    func testForeignDuplicateWithdrawnAndUnavailableSelectionsBorrowNoFigureOrRing() {
        let original = Self.kok
        let trade = original.trades[60]
        let foreign = Self.kokNo.trades[60]
        // Another original's trade id.
        let foreignInput = Self.input(original, .final, series: Self.series(original, .final, recorded: Self.observed(foreign)),
                                      inspected: trade,
                                      inspection: FieldHistoryInspection10868(
                                          x: foreign.x, caption: foreign.clock,
                                          selections: [original.seriesID: .point(id: foreign.id, spoken: foreign.figure)],
                                          choices: [], choicePresentation: .slider(label: "Inspect"), note: nil))
        XCTAssertNil(FieldHistoryGeometry10868.inspectedPoint(foreignInput.series[0], in: foreignInput))
        XCTAssertEqual(Self.slots(foreignInput).last?.display, .words(Self.unboundWords))
        // An observation reading for a different own trade than the inspected one.
        let mismatched = Self.input(original, .final, series: Self.series(original, .final, recorded: Self.observed(original.trades[61])),
                                    inspected: trade)
        XCTAssertEqual(FieldHistoryGeometry10868.inspectedPoint(mismatched.series[0], in: mismatched), Self.point(trade))
        XCTAssertEqual(Self.slots(mismatched).last?.display, .words(Self.unboundWords))
        // A duplicated trade id names no single observation.
        let duplicated = Self.input(original, .final,
                                    series: Self.series(original, .final, recorded: Self.observed(trade),
                                                        runs: Self.runs(original.trades + [trade])),
                                    inspected: trade)
        XCTAssertNil(FieldHistoryGeometry10868.inspectedPoint(duplicated.series[0], in: duplicated))
        XCTAssertEqual(Self.slots(duplicated).last?.display, .words(Self.unboundWords))
        // A baseline reading bound to another original's trade.
        let foreignBaseline = Self.input(original, .final,
                                         series: Self.series(original, .final, recorded: Self.observed(trade),
                                                             before: .observation(pointID: Self.kokNo.baselineID!, figure: "23%",
                                                                                  provenance: "foreign")),
                                         inspected: trade)
        XCTAssertEqual(Self.slots(foreignBaseline).first?.display, .words(Self.unboundWords))
        // An unavailable inspected reading keeps the owner's words.
        let unavailable = Self.input(original, .final, inspection: FieldHistoryInspection10868(
            x: trade.x, caption: trade.clock, selections: [original.seriesID: .absent(words: "No trade at this moment")],
            choices: [], choicePresentation: .slider(label: "Inspect"), note: nil))
        XCTAssertEqual(Self.slots(unavailable).last?.display, .words("No trade at this moment"))
        XCTAssertNil(FieldHistoryGeometry10868.inspectedPoint(unavailable.series[0], in: unavailable))
        // Withdrawn or missing selections show the owner's words, never a neighbour.
        XCTAssertEqual(FieldHistoryGeometry10868.selectedSummary(
            Self.input(original, .final, inspected: trade, selection: .unavailable(words: "Withdrawn"))), .words("Withdrawn"))
        XCTAssertEqual(FieldHistoryGeometry10868.selectedSummary(
            Self.input(original, .final, inspected: trade,
                       selection: .series(id: Self.kokNo.seriesID, missingWords: Self.missingWords))), .words(Self.missingWords))
        // Two originals sharing one id lose the ring and every observation-bound figure.
        let shared = Self.input(original, .final, inspected: trade)
        let twice = FieldHistoryInput10868(
            title: shared.title, caption: shared.caption,
            series: [Self.series(original, .final, recorded: Self.observed(trade)), Self.series(original, .final)],
            selection: shared.selection, domain: shared.domain, ceiling: shared.ceiling, yTicks: shared.yTicks,
            xTicks: shared.xTicks, guides: shared.guides, breaks: [], readout: shared.readout, markKey: shared.markKey,
            comparisonExplanation: nil, notes: shared.notes, summary: shared.summary, plotHeight: shared.plotHeight,
            unboundReadingWords: shared.unboundReadingWords, plotUnavailableWords: nil, windows: nil, scale: nil,
            moreOriginals: nil, details: nil, expand: nil, inspect: nil, previous: nil, next: nil,
            inspection: shared.inspection, layout: .focused)
        XCTAssertNil(FieldHistoryGeometry10868.inspectedPoint(twice.series[0], in: twice))
        XCTAssertEqual(FieldHistoryGeometry10868.selectedSummary(twice), .words(Self.missingWords))
        XCTAssertEqual(FieldHistoryGeometry10868.display(twice.series[0].before, of: twice.series[0], in: twice),
                       .words(Self.unboundWords))
    }
